    {'field': 'uploaded_by_role', 'label': 'Uploaded By Role (Auto)', 'section_name': 'PROPERTY UPLOADED BY (AUTO GENERATED)'},
    {'field': 'upload_file_name', 'label': 'Upload File Name', 'section_name': 'PROPERTY UPLOADED BY (AUTO GENERATED)'},

