def safe_float(val):
    """Safely converts Excel cell values to float, handling strings, currencies, and spaces."""
    if val is None:
        return 0.0
    try:
        if isinstance(val, (int, float)):
            return float(val)
        clean_val = str(val).replace('₹', '').replace(',', '').strip()
        return float(clean_val)
    except (ValueError, TypeError):
        return 0.0






